      "codigo_refatorado": "using UnityEngine;
using UnityEngine.Rendering;

public class AdaptiveQualityController : MonoBehaviour
{
    [Header("Configurações de Resolução Dinâmica")]
    [SerializeField] private float targetFrameTimeMs = 16.0f;
    [SerializeField] private float minScale = 0.70f;
    [SerializeField] private float maxScale = 1.0f;
    [SerializeField] private float adjustmentSpeed = 0.05f;
    private float currentScale = 1.0f;
    private FrameTiming[] frameTimings = new FrameTiming[1];

    private void Start()
    {
        QualitySettings.vSyncCount = 0;
        Application.targetFrameRate = 60;
    }

    private void Update()
    {
        FrameTimingManager.CaptureFrameTimings();
        uint count = FrameTimingManager.GetLatestTimings(1, frameTimings);

        if (count > 0)
        {
            float currentGpuMs = (float)frameTimings[0].gpuFrameTime;
            if (currentGpuMs <= 0.0f)
            {
                currentGpuMs = Time.unscaledDeltaTime * 1000.0f;
            }

            if (currentGpuMs > targetFrameTimeMs && currentScale > minScale)
            {
                currentScale = Mathf.Max(minScale, currentScale - adjustmentSpeed * Time.unscaledDeltaTime * 10f);
                ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
            }
            else if (currentGpuMs < (targetFrameTimeMs - 2.5f) && currentScale < maxScale)
            {
                currentScale = Mathf.Min(maxScale, currentScale + adjustmentSpeed * Time.unscaledDeltaTime * 5f);
                ScalableBufferManager.ResizeBuffers(currentScale, currentScale);
            }
        }
    }
}",
      "explicacao_didatica": "A placa de vídeo está demorando 26 milissegundos para pintar a imagem na tela, mas para rodar liso a 60 quadros por segundo ela só tem 16 milissegundos. Quando isso acontece sem muitos objetos na tela (poucos Draw Calls), significa que cada pixel está exigindo cálculos demais da GPU. O script implementado usa a Resolução Dinâmica nativa da Unity: se ele percebe que a GPU está demorando para entregar o quadro, reduz levemente a contagem de pixels da imagem interna antes de desenhá-la, aliviando a placa de vídeo de forma imperceptível e garantindo os 60 FPS cravados."
    },
    {
      "tipo": "GC",
      "causa_raiz": "Alocação de aproximadamente 33.7 KB de memória gerenciada no heap durante o frame capturado. Em 60 FPS, alocações contínuas nessa faixa geram mais de 2 MB de lixo por segundo, forçando pausas frequentes e engasgos (stuttering) causados pelo Garbage Collector em hardwares legados.",
      "codigo_refatorado": "using UnityEngine;
using TMPro;
using System.Text;

public class ZeroAllocationScoreHUD : MonoBehaviour
{
    [SerializeField] private TextMeshProUGUI scoreText;
    private static readonly StringBuilder stringBuilder = new StringBuilder(32);
    private int cachedScore = -1;

    public void UpdateScoreDisplay(int currentScore)
    {
        if (currentScore == cachedScore) return;
        cachedScore = currentScore;

        stringBuilder.Clear();
        stringBuilder.Append("PONTOS: ");
        stringBuilder.Append(currentScore);

        scoreText.SetText(stringBuilder);
    }
}",
      "explicacao_didatica": "Toda vez que juntamos textos ou criamos variáveis novas dentro do Update usando códigos simples como 'texto.text = pontuacao.ToString()', a Unity cria um pedaço de memória temporária que logo é jogado no lixo. Quando esse lixo acumula, o jogo dá uma travadinha para limpar tudo. A refatoração ensina a guardar o valor anterior e usar um construtor de texto reutilizável (StringBuilder), sem criar nenhum lixo por quadro."
    }
  ],
  "dicas_level_design": null
}

